//! 🧪️ Neutral call custody refuses retirement until its actual original vault returns the output.
use super::*;
use semio_framework_value_retirement::{NativeAllocationRefusal,NativeAllocationRefusalVault,RetainedAllocationEffect,RetainedCloneGrant,ValueRefusalKind,admit_retirement_cursor};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]
fn original_call_output_and_independent_refusals_survive_a_blocked_retirement(){
 let law:serde_json::Value=serde_json::from_str(include_str!("causes.json")).unwrap();let mut vault=NativeAllocationRefusalVault::default();let handle=vault.retain(ValueError::literal(ValueRefusalKind::Canceled,"output")).unwrap();
 let mut original=Some(NativeCallFailure{output:Some(NativeAllocationRefusal::Retained(handle)),operation:Some(ValueError::literal(ValueRefusalKind::InvalidValue,"operation")),context:Some(ValueError::literal(ValueRefusalKind::DepthLimit,"context")),receipt_refusal:Some(ValueError::literal(ValueRefusalKind::OwnershipLimit,"receiptRefusal"))});let pointer=original.as_ref().unwrap()as*const _ as usize;
 assert_eq!(original.as_ref().unwrap().retirement_ready(),law["readyBefore"].as_bool().unwrap());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual);let(turn,heap)=observe(||admit_retirement_cursor(&mut original,&mut effect));assert_eq!(heap,(0,0));assert_eq!(actual,None);assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.is_err());assert_eq!(original.as_ref().unwrap()as*const _ as usize,pointer);
 let owner=original.as_mut().unwrap();assert_eq!(owner.operation.as_ref().unwrap().message,law["channels"][1].as_str().unwrap());assert_eq!(owner.context.as_ref().unwrap().message,law["channels"][2].as_str().unwrap());assert_eq!(owner.receipt_refusal.as_ref().unwrap().message,law["channels"][3].as_str().unwrap());let handle=match owner.output.take().unwrap(){NativeAllocationRefusal::Retained(handle)=>handle,_=>panic!("original vault handle was replaced")};let returned=vault.take(handle).unwrap();assert_eq!(returned.message,law["channels"][0].as_str().unwrap());owner.output=Some(NativeAllocationRefusal::Owned(returned));assert_eq!(owner.retirement_ready(),law["readyAfter"].as_bool().unwrap());assert!(vault.terminal_is_empty());
}

static PRIVATE_SEED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
struct PrivateText(String);
impl RetireOwned for PrivateText{
 type RetirementCursor=<String as RetireOwned>::RetirementCursor;
 fn retirement_seed(self)->Self::RetirementCursor{PRIVATE_SEED_POINTER.store(self.0.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);self.0.retirement_seed()}
 fn controlled_retirement_supported()->bool{true}
}
pub struct PrivateOutputRecord{label:String,secret:PrivateText}
semio_framework_value_retirement::artifact_retire_struct!(PrivateOutputRecord{label,secret});
struct PhysicalTurns{actual:Option<usize>,allocated:usize,released:usize}
impl PhysicalTurns{
 fn step<T:RetireOwned>(&mut self,owner:&mut retirement::controlled::ControlledRetirement<T>,grant:RetainedCloneGrant,work:u64)->Result<semio_framework_value_retirement::RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>{
  self.actual=None;let mut effect=RetainedAllocationEffect::new(grant,work,&mut self.actual);let(turn,heap)=observe(||owner.step(&mut effect));assert_eq!(self.actual.unwrap_or(0),heap.0);let progress=turn.as_ref().map_or_else(|error|error.retained_progress(),|step|step.progress());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(owner.last_turn_work()<=work);self.allocated+=heap.0;self.released+=heap.1;turn
 }
}
fn record_grant(demand:semio_framework_value_retirement::RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)}}
#[test]
fn private_record_output_survives_source_and_child_birth_denials_and_closes_every_original_text(){
 let law:serde_json::Value=serde_json::from_str(include_str!("causes.json")).unwrap();let law=&law["record"];let text=|key:&str|law[key].as_str().unwrap().to_owned();let label=text("label");let secret=text("secret");let operation=text("operation");let context=text("context");let receipt=text("receiptRefusal");let owned_bytes=label.capacity()+secret.capacity()+operation.capacity()+context.capacity()+receipt.capacity();assert_eq!(owned_bytes,law["utf8Bytes"].as_u64().unwrap()as usize);let pointers=[label.as_ptr()as usize,secret.as_ptr()as usize,operation.as_ptr()as usize,context.as_ptr()as usize,receipt.as_ptr()as usize];
 let original=NativeCallFailure{output:Some(PrivateOutputRecord{label,secret:PrivateText(secret)}),operation:Some(ValueError::new(ValueRefusalKind::InvalidValue,operation)),context:Some(ValueError::new(ValueRefusalKind::Canceled,context)),receipt_refusal:Some(ValueError::new(ValueRefusalKind::OwnershipLimit,receipt))};let mut owner=retirement::controlled::ControlledRetirement::retain(original);let mut witness=PhysicalTurns{actual:None,allocated:0,released:0};PRIVATE_SEED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);
 let(probe,heap)=observe(||Vec::<u8>::with_capacity(73));assert_eq!(heap,(73,0));assert_eq!(observe(||drop(probe)).1,(0,73));
 for _ in 0..32{let demand=owner.next_demand(65536).unwrap();if demand.copy_bytes!=0{break}witness.step(&mut owner,record_grant(demand),1).unwrap();}let source=owner.original().unwrap()as*const _ as usize;let demand=owner.next_demand(65536).unwrap();assert!(demand.copy_bytes>0&&demand.capacity_bytes>0);
 for axis in law["sourceDenials"].as_array().unwrap(){let mut grant=record_grant(demand);let work=match axis.as_str().unwrap(){"work"=>0,"copy"=>{grant.maximum_copy_bytes-=1;1},"capacity"=>{grant.maximum_capacity_bytes-=1;1},_=>panic!("unknown source denial")};let before=(witness.allocated,witness.released);assert_eq!(witness.step(&mut owner,grant,work).unwrap().progress(),Default::default());assert_eq!(owner.last_turn_work(),0);assert_eq!((witness.allocated,witness.released),before);assert_eq!(owner.original().unwrap()as*const _ as usize,source);let original=owner.original().unwrap();assert_eq!(original.output.as_ref().unwrap().label.as_ptr()as usize,pointers[0]);assert_eq!(original.output.as_ref().unwrap().secret.0.as_ptr()as usize,pointers[1]);assert_eq!(original.operation.as_ref().unwrap().message.as_ptr()as usize,pointers[2]);assert_eq!(original.context.as_ref().unwrap().message.as_ptr()as usize,pointers[3]);assert_eq!(original.receipt_refusal.as_ref().unwrap().message.as_ptr()as usize,pointers[4]);assert_eq!(PRIVATE_SEED_POINTER.load(std::sync::atomic::Ordering::Relaxed),0);}
 witness.step(&mut owner,record_grant(demand),1).unwrap();assert!(owner.original().is_none());let mut child_births=0;let mut finished=false;
 for _ in 0..512{if owner.terminal_is_empty(){finished=true;break}let demand=owner.next_demand(65536).unwrap();let grant=record_grant(demand);if demand.capacity_bytes>0{child_births+=1;for axis in law["childDenials"].as_array().unwrap(){if axis=="copy"&&demand.copy_bytes==0{continue}let mut denied=grant;let work=match axis.as_str().unwrap(){"work"=>0,"copy"=>{denied.maximum_copy_bytes-=1;1},"capacity"=>{denied.maximum_capacity_bytes-=1;1},_=>panic!("unknown child denial")};let before=(witness.allocated,witness.released);assert_eq!(witness.step(&mut owner,denied,work).unwrap().progress(),Default::default());assert_eq!(owner.last_turn_work(),0);assert_eq!((witness.allocated,witness.released),before);assert_eq!(owner.next_demand(65536).unwrap(),demand);}}witness.step(&mut owner,grant,1).unwrap();}
 assert!(finished);assert!(child_births>=law["ownedStrings"].as_u64().unwrap()as usize);assert_eq!(PRIVATE_SEED_POINTER.load(std::sync::atomic::Ordering::Relaxed),pointers[1]);assert_eq!(witness.released,witness.allocated+owned_bytes);let empty=owner.next_demand(65536).unwrap();assert_eq!(witness.step(&mut owner,record_grant(empty),0).unwrap().progress(),Default::default());assert_eq!(owner.last_turn_work(),0);assert_eq!(observe(||drop(owner)).1,(0,0));
}
